fn track(f:&musicos_tauri::analysis::Features)->musicos_tauri::dj_plan::Track<'_>{musicos_tauri::dj_plan::Track{key_index:if f.key_confidence>=0.5{f.key_index}else{None},duration:f.structure.as_ref().map(|s|s.duration).unwrap_or(0.),bpm:f.bpm,structure:f.structure.as_ref()}}
// Read-only planner coverage on cached real-recording analysis; not accuracy acceptance.
fn main()->anyhow::Result<()>{let path=std::env::args().nth(1).ok_or_else(||anyhow::anyhow!("Pass library database"))?;let db=rusqlite::Connection::open_with_flags(path,rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)?;let mut q=db.prepare("SELECT d.result FROM tracks t JOIN desktop_dsp_v1 d ON d.track_id=t.id WHERE lower(t.album) IN ('discovery','junk','currents') AND t.deleted_at IS NULL AND d.version='dsp-4-dp-onsets-11025-4096-512'")?;let rows=q.query_map([],|r|r.get::<_,String>(0))?;let mut features=Vec::new();for row in rows{features.push(serde_json::from_str::<musicos_tauri::analysis::Features>(&row?)?);}let config=musicos_tauri::dj_plan::Config{enabled:true,..Default::default()};let mut plans=0;for(i,a)in features.iter().enumerate(){for(j,b)in features.iter().enumerate(){if i!=j&&musicos_tauri::dj_plan::plan(track(a),track(b),&config,false).is_some_and(|p|p.confidence>=0.5){plans+=1;}}}println!("{}",serde_json::json!({"recordings":features.len(),"pairs":features.len()*(features.len().saturating_sub(1)),"supported_musical_plans":plans,"baseline_version":"dsp-4-dp-onsets-11025-4096-512","accuracy_acceptance":false}));Ok(())}
